const {x, y, z, orientation} = msg.payload;
const pitch = Math.atan2(-x, Math.sqrt(y * y + z * z)) * 180 / Math.PI;
const roll  = Math.atan2(y, z) * 180 / Math.PI;
const LAPO = ['portrait up', 'portrait down', 'landscape right', 'landscape left'];
let screen = 'unknown';
if (orientation) {
    screen = LAPO[orientation.portrait_landscape];
    if (orientation.back) { screen += ', back'; } else { screen += ', front'; }
}
msg.payload = { x, y, z, pitch, roll, screen, orientation };
return msg;
